// Built-in content engine: word banks + generators used when no LLM key is set (or the LLM is
// slow/rejected). Each generator takes a context `c` ({vars, players, mem, rng}) and returns a string.
// When ANTHROPIC_API_KEY is present the same slots are generated by the model instead.

export const pick = (arr, rng = Math.random) => arr[Math.floor(rng() * arr.length)];
export const shuffle = (arr, rng = Math.random) => {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
};

