export const FALLBACKS = {
  crime: () => pick(CRIMES),
  evidence: () => pick(EVIDENCE),
  sentence: () => pick(SENTENCES),
  species: () => pick(SPECIES),
  ritual: () => pick(RITUALS),
  missing_thing: () => pick(MISSING),
  floor_material: () => pick(FLOORS),
  alien_question: () => pick(QUESTIONS),
  door_result: () => pick(BEHIND_DOOR),
  dream_line: () => pick(DREAM_LINES),
  cosmic_name: () => `${pick(COSMIC_FIRST)} ${pick(COSMIC_MID)} ${pick(COSMIC_LAST)}`,
  readout: (c) => {
    const parts = shuffle(READOUT_PARTS, c.rng).slice(0, 3);
    const a = 40 + Math.floor(c.rng() * 40), b = Math.floor(c.rng() * (100 - a - 5)), d = 100 - a - b;
    return `${a}% ${parts[0]}, ${b}% ${parts[1]}, ${d}% ${parts[2]}.`;
  },
  creature: (c) => {
    const bits = shuffle(['Moth', 'Lantern', 'Gloop', 'Beak', 'Sock', 'Orb', 'Choir', 'Tooth', 'Hum', 'Noodle', 'Cloud', 'Drum'], c.rng);
    return `The ${bits[0]}-${bits[1]} (${pick(['feeds on small silences', 'is afraid of exactly one chair', 'hums in the key of Wednesday', 'has four opinions and no mouth', 'is mostly eyelashes', 'weighs less than a rumor'])})`;
  },
  mistranslation: (c) => {
    const t = (c.vars.last_text || 'something').slice(0, 60);
    return `Mistranslated from Human: "${t}" is a sacred rite of ${pick(RITUALS)}.`;
  },
  word_prophecy: (c) => {
    const w = (c.vars.words || []).filter(Boolean);
    if (w.length < 2) return 'The words said nothing. Which is also prophecy.';
    const s = shuffle(w, c.rng);
    return `It is written: the ${s[0]} ${pick(JOIN)} ${s[1] ? 'consume' : 'wait'} the ${s[1] || 'void'}${s[2] ? `, and the ${s[2]} will not be consulted` : ''}.`;
  },
  field_report: (c) => {
    const m = c.mem;
    const quiet = m?.quietest || pick(c.players, c.rng) || 'someone';
    const top = m?.mostChosen || pick(c.players, c.rng) || 'someone';
    return pick(FIELD, c.rng).replaceAll('{quiet}', quiet).replaceAll('{top}', top).replaceAll('{n}', String(m?.eventCount ?? 0));
  },
  conclusion: (c) => {
    const who = c.vars.leader || 'one of you';
    return `${who} has been classified as ${pick(SPECIES)}. The others are merely suspicious.`;
  },
  law: () => pick(['Must refer to the nearest lamp as "Sir".', 'Must sigh whenever someone says "okay".', 'Must announce each sip of any beverage like weather.', 'Must greet the next object they touch.']),
  free: () => 'Something has happened.',
};

